import{c as t,Q as o,j as e,m as r}from"./chunks/framework.DOi4mjdC.js";const d=JSON.parse('{"title":"儒林外史","description":"","frontmatter":{"id":"rulinwaishi","title":"儒林外史","author":"吴敬梓","dynasty":"清代","cover":"/covers/rulinwaishi.jpg","sort":1,"literaryValue":"《儒林外史》是清代吴敬梓创作的长篇讽刺小说，以写实主义描绘了各类人士对于\\"功名富贵\\"的不同表现，是中国古代讽刺小说的高峰。"},"headers":[],"relativePath":"books/xiaoshuo/rulinwaishi.md","filePath":"books/xiaoshuo/rulinwaishi.md"}'),i={name:"books/xiaoshuo/rulinwaishi.md"};function u(s,a,n,h,l,p){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="儒林外史" tabindex="-1">儒林外史 <a class="header-anchor" href="#儒林外史" aria-label="Permalink to &quot;儒林外史&quot;">​</a></h1><h2 id="作品简介" tabindex="-1">作品简介 <a class="header-anchor" href="#作品简介" aria-label="Permalink to &quot;作品简介&quot;">​</a></h2><p>《儒林外史》是清代吴敬梓创作的长篇小说，成书于乾隆十四年（1749年）或稍前，现以抄本传世，初刻于嘉庆八年（1803年）。</p><p>全书五十六回，以写实主义描绘各类人士对于&quot;功名富贵&quot;的不同表现，一方面真实的揭示人性被腐蚀的过程和原因，从而对当时吏治的腐败、科举的弊端礼教的虚伪等进行了深刻的批判和嘲讽；一方面热情地歌颂了少数人物以坚持自我的方式所作的对于人性的守护，从而寄寓了作者的理想。</p><p>小说白话的运用已趋纯熟自如，人物性格的刻画也颇为深入细腻，尤其是采用高超的讽刺手法，使该书成为中国古典讽刺文学的佳作。</p><h2 id="作者介绍" tabindex="-1">作者介绍 <a class="header-anchor" href="#作者介绍" aria-label="Permalink to &quot;作者介绍&quot;">​</a></h2><p><strong>吴敬梓</strong>（1701年—1754年），字敏轩，一字文木，号粒民，安徽省滁州市全椒县人。清代小说家。因家有&quot;文木山房&quot;，所以晚年自称&quot;文木老人&quot;，又因自家乡安徽滁州全椒县移至江苏南京秦淮河畔，故又称&quot;秦淮寓客&quot;。</p><p>吴敬梓出身科举世家，早年生活豪纵，后家业衰落，移居江宁。乾隆初荐举博学鸿词，托病不赴，穷困以终。工诗词散文，尤以长篇小说《儒林外史》成就最高。</p><h2 id="文学价值" tabindex="-1">文学价值 <a class="header-anchor" href="#文学价值" aria-label="Permalink to &quot;文学价值&quot;">​</a></h2><p>《儒林外史》代表着中国古代讽刺小说的高峰，它开创了以小说直接评价现实生活的范例。《儒林外史》脱稿后即有手抄本传世，后人评价甚高，鲁迅认为该书思想内容&quot;秉持公心，指摘时弊&quot;，胡适认为其艺术特色堪称&quot;精工提炼&quot;。在国际汉学界，该书更是影响颇大，早有英、法、德、俄、日、西班牙等多种文字传世，并获汉学界盛赞，有认为《儒林外史》足堪跻身于世界文学杰作之林，可与薄伽丘、塞万提斯、巴尔扎克或狄更斯等人的作品相提并论，是对世界文学的卓越贡献。</p><h2 id="第一回-说楔子敷陈大义-借名流隐括全文" tabindex="-1">第一回 说楔子敷陈大义 借名流隐括全文 <a class="header-anchor" href="#第一回-说楔子敷陈大义-借名流隐括全文" aria-label="Permalink to &quot;第一回 说楔子敷陈大义 借名流隐括全文&quot;">​</a></h2><p>人生南北多歧路，将相神仙，也要凡人做。百代兴亡朝复暮，江风吹倒前朝树。</p><p>功名富贵无凭据，费尽心情，总把流光误。浊酒三杯沉醉去，水流花谢知何处。</p><p>这一首词，也是个老生常谈。不过说人生富贵功名，是身外之物；但世人一见了功名，便舍着性命去求他，及至到手之后，味同嚼蜡。自古及今，那一个是看得破的！</p><p>虽然如此说，元朝末年，也曾出了一个嵚崎磊落的人。这人姓王名冕，在诸暨县乡村居住。他七岁时死了父亲，他母亲做些针指，供给他到村学堂里去读书。看看三个年头，王冕已是十岁了。母亲唤他到面前来说道：&quot;儿啊！不是我有心要耽误你。只因你父亲亡后，我一个寡妇人家，只有出去的，没有进来的；年岁不好，柴米又贵；这几件旧衣服和些旧家伙，当的当了，卖的卖了；只靠着我替人家做些针指生活寻来的钱，如何供得你读书。如今没奈何，把你雇在间壁人家放牛，每月可以得他几钱银子，你又有现成饭吃，只在明日就要去了。&quot;王冕道：&quot;娘说的是。我在学堂里坐着，心里也闷；不如往他家放牛，倒快活些。假如我要读书，依旧可以带几本去读。&quot;当夜商议定了。</p><p>第二日，母亲同他到间壁秦老家。秦老留着他母子两个吃了早饭，牵出一条水牛来交与王冕，指着门外道：&quot;就在我这大门过去两箭之地，便是七泖湖，湖边一带绿草，各家的牛都在那里打睡。又有几十伙合抱的垂杨树，十分阴凉。牛要渴了，就在湖边上饮水。小哥，你只在这一带顽耍，不必远去。我老汉每日两餐小菜饭是不少的，每日早上，还折两个钱与你买点心吃。只是百事勤谨些，休嫌怠慢。&quot;他母亲谢了扰要回家去，王冕送出门来。母亲替他理理衣服，口里说道：&quot;你在此须要小心，休惹人说不是；早出晚归，免我悬望。&quot;王冕应诺，母亲含着两眼眼泪去了。</p><p>王冕自此只在秦家放牛，每到黄昏，回家跟着母亲歇宿。或遇秦家煮些腌鱼、腊肉给他吃，他便拿块荷叶包了来家，递与母亲。每日点心钱，他也不买了吃，聚到一两个月，便偷个空，走到村学堂里，见那闯学堂的书客，就买几本旧书，日逐把牛拴了，坐在柳阴树下看。</p><h2 id="作品评价" tabindex="-1">作品评价 <a class="header-anchor" href="#作品评价" aria-label="Permalink to &quot;作品评价&quot;">​</a></h2><p>《儒林外史》是中国古代讽刺文学的典范，吴敬梓对生活在封建末世和科举制度下的封建文人群像的成功塑造，以及对吃人的科举、礼教和腐败事态的生动描绘，使他成为我国文学史上批判现实主义的杰出作家之一。《儒林外史》不仅直接影响了近代谴责小说，而且对现代讽刺文学也有深刻的启发。</p>',19)])])}const c=t(i,[["render",u]]);export{d as __pageData,c as default};
